import {inboxRecord,saveInboxComparison,backToInbox} from './workflow-bridge.js';
import {sourceStamp,invoiceFor,assertContext} from './workflow-engine.js';
import {confirmSupplier} from './supplier.js';
import {startResolutionCase} from './case-ui.js';
import {extractAndReview} from './extraction-review.js';
import {money} from './engine.js';
import {renderLineMatchReview} from './line-match-review.js';
import {validateDocument,compareDocuments,correctionDraft,reviewedExport,reviewCsv} from './matching-engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let invoice=null,po=null,result=null,reviewed=false,inboxContext=null,lineDecisions=[];
const root=document.createElement('section');root.id='matching-page';root.innerHTML=`<div class="match-hero"><div><span class="eyebrow">THE $60 EXCEPTION</span><h2>Catch the difference.<br>Make the next step easy.</h2><p>Follow one invoice from intake to an evidence-backed correction request.</p></div><div class="hero-equation"><span>INVOICED</span><b>$660</b><i>vs.</i><b>$600</b><span>ORDERED</span></div></div><div class="match-steps"><span><b>1</b> Add documents</span><span><b>2</b> Compare & explain</span><span><b>3</b> Draft a correction</span><span><b>4</b> Review & export</span></div><section class="panel match-intake"><div class="panel-heading"><div><h2>Start with the source documents</h2><p>Upload a PDF, image or JSON for each document, or load the example. Use matching currencies for comparison. English OCR runs in this browser.</p></div><button id="load-pair" class="button primary">Load $60 example</button></div><div class="pair-upload"><div><label for="match-invoice">Invoice document</label><input id="match-invoice" type="file" accept=".json,.pdf,.png,.jpg,.jpeg,.webp,application/json,application/pdf,image/png,image/jpeg,image/webp"><a href="samples/matching-invoice.json" download>↓ Download sample invoice (.json)</a><a href="samples/matching-invoice.pdf" download>↓ Invoice PDF</a><a href="samples/matching-invoice.png" download>↓ Invoice image</a></div><div><label for="match-po">Purchase order</label><input id="match-po" type="file" accept=".json,.pdf,.png,.jpg,.jpeg,.webp,application/json,application/pdf,image/png,image/jpeg,image/webp"><a href="samples/matching-po.json" download>↓ Download sample purchase order (.json)</a><a href="samples/matching-po.pdf" download>↓ Purchase order PDF</a></div></div><p class="match-note">PDF text extraction and image/scanned-PDF OCR run in your browser. Review extracted fields before comparing. Up to 15 MB and 5 PDF pages. Email sending is not connected.</p><div id="match-error" class="match-error" role="alert" hidden></div><div class="panel-footer"><span id="pair-status">Add an invoice and its purchase order to begin.</span><button id="compare-pair" class="button primary" disabled>Compare documents →</button></div></section><div id="pair-documents" class="pair-documents"></div><section id="match-results" hidden></section><div id="match-message" role="status" class="match-message"></div>`;
$('.content').insertBefore(root,$('footer'));
function message(s){$('#match-message').textContent=s;}
function error(e){$('#match-error').hidden=false;$('#match-error').textContent=e.message;if(e.code==='SUPPLIER_REVIEW'){const form=document.createElement('form');form.innerHTML='<label><input type="checkbox" required> I verified both names refer to the same supplier.</label><label>Supplier verification note<input name="note" required placeholder="How did you verify the supplier?"></label><button class="button secondary">Confirm supplier & compare</button>';form.onsubmit=event=>{event.preventDefault();try{invoice=confirmSupplier(invoice,po,new FormData(form).get('note'));$('#compare-pair').click();}catch(err){error(err);}};$('#match-error').append(form);}}
function invalidate(){result=null;reviewed=false;$('#match-results').hidden=true;$('#match-results').innerHTML='';message('');$('#match-error').hidden=true;}
function documentCard(d,title){const format=n=>money(n,d.pricingCurrency||d.currency);return `<article class="source-card"><div class="source-heading"><span class="eyebrow">${title}</span><span class="demo-badge">SOURCE DOCUMENT</span></div><h3>${esc(d.vendor)}</h3><div class="source-meta"><span>${esc(d.number)}</span><span>PO reference: ${esc(d.poNumber)}</span></div><table><thead><tr><th>LINE / ITEM</th><th>QTY</th><th>UNIT</th><th>AMOUNT</th></tr></thead><tbody>${d.lines.map((l,i)=>`<tr class="${result?.lines.some(r=>r.changed&&(title==='INVOICE'?r.invoiceLine:r.poLine)===i+1)?'evidence-highlight':''}"><td><small>Line ${i+1} · ${esc(l.sku)}</small><strong>${esc(l.description)}</strong></td><td>${l.quantity}</td><td>${format(l.unitPrice)}</td><td>${l.amount!=null?format(l.amount):format(l.quantity*l.unitPrice)}${l.amount!=null?'<small>Printed amount</small>':'<small>Calculated</small>'}</td></tr>`).join('')}</tbody></table><div class="source-totals"><span>Tax ${format(d.tax)}</span><strong>Total ${money(d.total,d.currency)}</strong></div><details><summary>View document data and extracted text</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details><p class="hint">${esc(d.note||'Imported document. Verify the source before making a decision.')}</p></article>`;}
function renderSources(){ $('#match-invoice').disabled=!!inboxContext;$('#load-pair').disabled=!!inboxContext; $('#pair-documents').innerHTML=(invoice?documentCard(invoice,'INVOICE'):'')+(po?documentCard(po,'PURCHASE ORDER'):'');$('#compare-pair').disabled=!(invoice&&po);
 if(inboxContext)linkedBanner.querySelector('[data-match-instructions]').textContent=po
  ? 'The invoice and purchase order are loaded. Click Compare documents to check for discrepancies.'
  : 'The invoice is loaded. Attach its purchase order, then click Compare documents.';
 $('#pair-status').textContent=invoice&&po?'Two documents loaded. Ready to compare.':invoice||po?'One document loaded. Add the other to continue.':'Add an invoice and its purchase order to begin.';}
async function upload(e,kind){const file=e.target.files[0];if(!file)return;lineDecisions=[];invalidate();if(kind==='invoice')invoice=null;else po=null;renderSources();const controls=['#match-invoice','#match-po','#compare-pair','#load-pair'];controls.forEach(s=>$(s).disabled=true);try{let d;if(file.name.toLowerCase().endsWith('.json')){if(file.size>500000)throw Error('JSON documents must be under 500 KB.');d=validateDocument(JSON.parse(await file.text()),kind,{allowMissingInvoiceAmounts:true});}else{d=await extractAndReview(file,kind,message);}if(d){delete d.supplierReview;if(kind==='invoice')invoice=d;else po=d;message('Verified document loaded. Add the other document or compare.');}else message('Extraction canceled. Choose a document to try again.');}catch(e){error(e instanceof SyntaxError?Error('Invalid JSON document.'):e);}finally{controls.forEach(s=>$(s).disabled=false);e.target.value='';renderSources();}}
$('#match-invoice').onchange=e=>upload(e,'invoice');$('#match-po').onchange=e=>upload(e,'purchase_order');
$('#load-pair').onclick=async()=>{lineDecisions=[];invalidate();$('#load-pair').disabled=true;try{const [i,p]=await Promise.all(['samples/matching-invoice.json','samples/matching-po.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Sample documents could not load. Please try again.');return r.json();}));invoice=validateDocument(i,'invoice');po=validateDocument(p,'purchase_order');$('#match-invoice').value='';$('#match-po').value='';renderSources();message('Sample documents loaded. Compare them to find the discrepancy.');}catch(e){error(e);}finally{$('#load-pair').disabled=false;}};
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#compare-pair').onclick=()=>{invalidate();try{if(inboxContext)assertContext(inboxRecord(inboxContext.id),inboxContext);result=compareDocuments(invoice,po,{lineDecisions,allowMissingInvoiceAmounts:true});if(inboxContext)saveInboxComparison(inboxContext,invoice,po,result);renderSources();renderResults();$('#match-results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){error(e);}};
function renderResults(){const format=n=>money(n,invoice.currency);const changed=result.lines.filter(l=>l.changed);const mismatch=result.hasDiscrepancy;
 const pending=result.pendingLineMatches.length>0;
 const missingAmounts=invoice.tax==null||invoice.total==null;
 const needsReview=pending||missingAmounts;
 const net=result.differenceCents;
 const headline=pending?'Review suggested product matches':mismatch?(net?format(Math.abs(net)/100)+' net '+(net<0?'undercharge':'overcharge'):'Line or amount differences found'):missingAmounts?'Review invoice amounts':'Invoice matches the purchase order';
 $('#match-results').hidden=false;$('#match-results').innerHTML=`<div class="result-banner ${mismatch||needsReview?'':'matched'}"><div><span class="eyebrow">${needsReview?'REVIEW REQUIRED':mismatch?'EXCEPTION DETECTED':'COMPARISON COMPLETE'}</span><h2>${headline}</h2><p>${pending?'Confirm product pairs to compare their prices.':missingAmounts?'Complete the invoice tax and total review before export.':mismatch?`${changed.length} changed line item${changed.length===1?'':'s'}. Review the evidence before contacting the vendor.`:'Amounts and line items agree. Payment still requires your separate approval.'}</p></div><span class="payment-hold">${mismatch||needsReview?'PAYMENT ON HOLD':'PAYMENT NOT APPROVED'}</span></div><section class="panel evidence-panel"><div class="panel-heading"><div><h2>The evidence</h2><p>${esc(result.vendorEvidence)} Line numbers point to the source documents above.</p></div></div><div class="evidence-list">${invoice.tax==null?'<p class="check">Invoice tax amount missing. Tax comparison is pending.</p>':''}${(result.arithmetic||[]).map(c=>`<div class="check"><strong>${esc(c.document)} arithmetic contradiction</strong><p>${esc(c.message)}</p></div>`).join('')}${result.lines.map(l=>`<article class="evidence-row ${l.changed?'changed':''}"><div><strong>${esc(l.description)}</strong><small>${esc(l.matchBasis==='reviewer_confirmed'?l.invoice.sku+' ↔ '+l.po.sku:l.sku)} · ${l.matchBasis==='exact_sku'?'Exact SKU':l.matchBasis==='reviewer_confirmed'?'Confirmed by reviewer':'Unmatched'}</small></div><div><small>INVOICE · LINE ${l.invoiceLine??'MISSING'}</small><strong>${l.invoice?`${l.invoice.quantity} × ${format(l.invoice.unitPrice)} = ${format(l.invoicedCents/100)}`:'Not on invoice'}</strong></div><div><small>PO · LINE ${l.poLine??'MISSING'}</small><strong>${l.po?`${l.po.quantity} × ${format(l.po.unitPrice)} = ${format(l.expectedCents/100)}`:'Not on PO'}</strong></div><b>${l.changed?format(l.differenceCents/100):'✓'}</b></article>`).join('')}${result.taxDifferenceCents?`<div class="check">Tax difference: ${format(result.taxDifferenceCents/100)}. Invoice tax ${format(invoice.tax)}; PO tax ${format(po.tax)}.</div>`:''}</div><div class="evidence-explanation">${changed.length===1&&changed[0].invoice?.quantity===changed[0].po?.quantity?`${changed[0].invoice.quantity} units × (${format(changed[0].invoice.unitPrice)} invoiced − ${format(changed[0].po.unitPrice)} ordered) = <strong>${format(changed[0].differenceCents/100)} line difference.</strong>`:'The net difference is the invoice total minus the purchase order total. Opposing line differences may cancel out.'} ${mismatch?'The original documents remain unchanged.':''}</div></section><div class="resolution-grid"><section class="panel correction-panel"><div class="panel-heading"><div><h2>Correction request</h2><p>An editable draft grounded in the comparison. You decide what to send.</p></div></div><div class="resolution-body">${mismatch?'<button id="make-draft" class="button secondary">Draft correction request</button><label for="correction-text" class="draft-label" hidden>Review and edit your message</label><textarea id="correction-text" rows="14" hidden></textarea><button id="download-draft" class="text-button" hidden>↓ Download draft (.txt)</button>':'<p>No correction request needed for these documents.</p>'}<p class="hint">Draft only. Nothing is sent automatically.</p></div></section><section class="panel export-panel"><div class="panel-heading"><div><h2>Review & export</h2><p>Record your review without authorizing payment.</p></div></div><div class="resolution-body"><div class="hold-card"><strong>${needsReview?'Review required':mismatch?'Awaiting vendor correction':'Awaiting user approval'}</strong><p>${needsReview?'Complete the comparison review before exporting.':mismatch?'Export keeps the discrepancy on hold.':'Export marks the evidence reviewed and payment NOT_APPROVED.'}</p></div><label class="review-confirm"><input type="checkbox" id="review-evidence" ${needsReview?'disabled':''}> I reviewed both documents and the comparison evidence.</label><div class="actions"><button id="review-csv" class="button primary" disabled>Export reviewed CSV</button><button id="review-json" class="button secondary" disabled>JSON + evidence</button></div><p class="hint">No payment is approved or initiated from this demo. Downloaded records include the review status and payment hold.</p></div></section></div>`;
 if(pending){
  const summarize=lines=>lines.map((line,index)=>({...line,id:index+1,number:index+1}));
  const review=renderLineMatchReview({candidates:result.pendingLineMatches,invoiceLines:summarize(invoice.lines),poLines:summarize(po.lines),
   onReview:(match,decision)=>{
    lineDecisions=[...lineDecisions,{invoiceLine:match.invoiceLine,poLine:match.poLine,decision}];
    $('#compare-pair').click();
   }});
  $('#match-results .result-banner').after(review);
 }
 if(!needsReview){
  const track=document.createElement('button');track.className='button primary';track.textContent='Track correction & resolution →';
  track.onclick=()=>startResolutionCase(invoice,po,inboxContext,lineDecisions);$('#match-results').append(track);
 }
 if(mismatch){$('#make-draft').onclick=()=>{$('#correction-text').hidden=false;$('.draft-label').hidden=false;$('#download-draft').hidden=false;$('#correction-text').value=correctionDraft(invoice,po,result);$('#make-draft').disabled=true;message('Correction request drafted. Review and edit it before downloading.');};$('#download-draft').onclick=()=>{download($('#correction-text').value,'correction-request.txt','text/plain');message('Draft downloaded. No message was sent.');};}
 $('#review-evidence').onchange=e=>{reviewed=e.target.checked;$('#review-csv').disabled=!reviewed;$('#review-json').disabled=!reviewed;};
 const exportData=format=>{try{if(inboxContext)assertContext(inboxRecord(inboxContext.id),inboxContext);const data=reviewedExport(invoice,po,result,reviewed);if(inboxContext)data.inboxInvoiceId=inboxContext.id;download(format==='csv'?reviewCsv(data):JSON.stringify(data,null,2),`reviewed-comparison.${format}`,format==='csv'?'text/csv':'application/json');message('Reviewed data exported. Payment remains '+data.paymentStatus.replaceAll('_',' ').toLowerCase()+'.');}catch(e){message(e.message);}};$('#review-csv').onclick=()=>exportData('csv');$('#review-json').onclick=()=>exportData('json');
}
window.addEventListener('invoicing-reset',()=>{inboxContext=null;invoice=null;po=null;lineDecisions=[];invalidate();$('#match-invoice').value='';$('#match-po').value='';renderSources();});

const linkedBanner=document.createElement('div');linkedBanner.className='notice';linkedBanner.hidden=true;root.prepend(linkedBanner);
export function openInboxMatch(doc){if(doc.status==='queued'||doc.status==='rejected')throw Error('Process this invoice before matching.');inboxContext={id:doc.id,stamp:sourceStamp(doc)};invoice=doc.workflow?.invoice?structuredClone(doc.workflow.invoice):invoiceFor(doc);po=doc.workflow?.po?structuredClone(doc.workflow.po):doc.purchaseOrder?structuredClone(doc.purchaseOrder):null;lineDecisions=doc.workflow?.comparison.lineDecisions??[];invalidate();linkedBanner.hidden=false;linkedBanner.innerHTML=`<div><strong>Inbox invoice ${esc(doc.fields.number)}</strong><p data-match-instructions></p><button class="text-button" data-back>← Back to invoice inbox</button><button class="text-button" data-detach>Start a separate comparison</button></div>`;linkedBanner.querySelector('[data-back]').onclick=backToInbox;linkedBanner.querySelector('[data-detach]').onclick=()=>{inboxContext=null;invoice=null;po=null;lineDecisions=[];invalidate();linkedBanner.hidden=true;renderSources();};renderSources();document.querySelector('[data-page=matching]').click();}
window.addEventListener('invoicing-reset',()=>{linkedBanner.hidden=true;});
